// Validation of the browser Kuhn CFR against the committed Python
// fixture (kuhn_reference.json is generated by
// scripts/build_web_research_data.py from the project's Python CFR).
// Both implementations are deterministic full-tree vanilla CFR, so at
// matching iteration counts the average strategies must agree to
// floating-point tolerance.

import { describe, expect, it } from "vitest";
import ref from "../data/lab/kuhn_reference.json";
import {
  ALL_DEALS,
  INFOSET_KEYS,
  KuhnCFR,
  bestResponse,
  exploitability,
  gameValue,
  utility,
} from "./kuhn";

const payload = (ref as any).payload;

describe("game rules", () => {
  it("enumerates 6 deals and 12 infosets", () => {
    expect(ALL_DEALS.length).toBe(6);
    expect(INFOSET_KEYS.length).toBe(12);
  });
  it("terminal utilities match the rules table", () => {
    expect(utility([2, 0], "bp")).toBe(1);
    expect(utility([0, 2], "pbp")).toBe(-1);
    expect(utility([2, 0], "pp")).toBe(1);
    expect(utility([0, 2], "bb")).toBe(-2);
    expect(utility([2, 1], "pbb")).toBe(2);
  });
});

describe("CFR matches the Python reference", () => {
  it("reproduces the committed average strategies at every checkpoint", () => {
    const solver = new KuhnCFR();
    let done = 0;
    for (const cp of payload.trace) {
      solver.train(cp.iteration - done);
      done = cp.iteration;
      const avg = solver.averageStrategy();
      for (const key of Object.keys(cp.strategy)) {
        for (const a of ["p", "b"] as const) {
          expect(avg[key][a]).toBeCloseTo(cp.strategy[key][a], 4);
        }
      }
    }
  });

  it("exploitability matches the Python exact evaluation", () => {
    const solver = new KuhnCFR();
    let done = 0;
    for (const cp of payload.trace) {
      solver.train(cp.iteration - done);
      done = cp.iteration;
      expect(exploitability(solver.averageStrategy())).toBeCloseTo(
        cp.exploitability,
        5,
      );
    }
  });

  it("converges toward the known game value -1/18", () => {
    const solver = new KuhnCFR();
    solver.train(10000);
    const v = gameValue(solver.averageStrategy());
    expect(v).toBeCloseTo(-1 / 18, 2);
    expect(exploitability(solver.averageStrategy())).toBeLessThan(0.01);
  });
});

describe("exact best response", () => {
  it("always-bet is exploited for the documented amount", () => {
    const alwaysBet: Record<string, Record<string, number>> = {};
    for (const k of INFOSET_KEYS) alwaysBet[k] = { p: 0, b: 1 };
    const e = exploitability(alwaysBet);
    expect(e).toBeGreaterThan(0.3); // clearly exploitable
    // BR values from both sides are at least the game value for that seat
    const v = gameValue(alwaysBet);
    expect(bestResponse(alwaysBet, 0).value).toBeGreaterThanOrEqual(v - 1e-9);
    expect(bestResponse(alwaysBet, 1).value).toBeGreaterThanOrEqual(-v - 1e-9);
  });

  it("near-equilibrium strategies are near-unexploitable (fixture)", () => {
    expect(exploitability(payload.final_policy)).toBeCloseTo(
      payload.final_exploitability,
      5,
    );
  });

  it("equilibrium structural facts hold for the trained policy", () => {
    const s = payload.final_policy;
    // With the King facing a bet, always call; with the Jack, never call.
    expect(s["2b"].b).toBeGreaterThan(0.98);
    expect(s["0b"].b).toBeLessThan(0.02);
    // Queen first to act checks (betting Q first is dominated in Kuhn eq).
    expect(s["1"].p).toBeGreaterThan(0.95);
  });
});
